import { type } from "arktype"

interface Ctx {
  defs: Record<string, any>
  cache: Map<string, any>
}

function makeCtx(defs: Record<string, any>): Ctx {
  return { defs, cache: new Map() }
}

function resolveDef(name: string, ctx: Ctx): any {
  const cached = ctx.cache.get(name)
  if (cached) return cached
  const t = parseJsonSchema(ctx.defs[name], ctx)
  ctx.cache.set(name, t)
  return t
}

function parseRef(name: string, ctx: Ctx): any {
  const existing = ctx.cache.get(name)
  if (existing) return existing
  const wrapper = type.unknown.narrow((data: unknown, traversalCtx: any) => {
    const resolved = resolveDef(name, ctx)
    return resolved.allows(data)
  })
  return wrapper
}

function parseJsonSchema(schema: any, ctx: Ctx): any {
  if (schema.$ref) {
    const name = schema.$ref.replace("#/$defs/", "")
    return parseRef(name, ctx)
  }
  if (schema.type === "object") {
    const props: any = {}
    for (const [k, v] of Object.entries(schema.properties ?? {})) {
      props[k] = parseJsonSchema(v, ctx)
    }
    return type({ ...props })
  }
  if (schema.type === "string") return type("string")
  if (schema.type === "null") return type("null")
  return type("unknown")
}

const defs = {
  Node: {
    type: "object",
    properties: {
      value: { type: "string" },
      next: { $ref: "#/$defs/Node" }
    }
  }
}
const ctx = makeCtx(defs)
const T = parseRef("Node", ctx)
