import { jsonSchemaToType, parseJsonSchema } from "@ark/json-schema"

const check = (name: string, schema: any, valid: any[], invalid: any[]) => {
  try {
    const t = jsonSchemaToType(schema)
    for (const v of valid) {
      if (!t.allows(v)) console.log(`FAIL ${name}: should allow`, JSON.stringify(v))
    }
    for (const v of invalid) {
      if (t.allows(v)) console.log(`FAIL ${name}: should reject`, JSON.stringify(v))
    }
    console.log(`ok ${name}`)
  } catch (e) {
    console.log(`ERROR ${name}:`, (e as Error).message)
  }
}

// dependentRequired
check("dependentRequired", {
  type: "object",
  dependentRequired: { credit_card: ["billing_address"] }
}, [{ credit_card: "x", billing_address: "y" }], [{ credit_card: "x" }])

// dependentSchemas
check("dependentSchemas", {
  type: "object",
  dependentSchemas: { foo: { required: ["bar"] } }
}, [{ foo: 1, bar: 2 }], [{ foo: 1 }])

// dependencies array
check("dependencies array", {
  type: "object",
  dependencies: { a: ["b"] }
}, [{ a: 1, b: 2 }], [{ a: 1 }])

// dependencies schema
check("dependencies schema", {
  type: "object",
  dependencies: { a: { required: ["b"] } }
}, [{ a: 1, b: 2 }], [{ a: 1 }])

// $ref simple
check("$ref simple", {
  $defs: { Name: { type: "string", minLength: 2 } },
  $ref: "#/$defs/Name"
}, ["ab", "abc"], ["a", 5])

// $ref invalid format
try {
  jsonSchemaToType({ $ref: "https://example.com/x" } as any)
  console.log("FAIL invalid ref format: no throw")
} catch (e) {
  const msg = (e as Error).message
  console.log(msg.includes("Only local $ref values of the form #/$defs/<name> are supported") ? "ok invalid ref format" : `FAIL invalid ref msg: ${msg}`)
}

// $ref non-existent
try {
  jsonSchemaToType({ $defs: {}, $ref: "#/$defs/NonExistentDef" } as any)
  console.log("FAIL non-existent ref: no throw")
} catch (e) {
  const msg = (e as Error).message
  console.log(msg.includes('Unable to resolve $ref "#/$defs/NonExistentDef" from root $defs') ? "ok non-existent ref" : `FAIL non-existent ref msg: ${msg}`)
}

// enum deep equality
check("enum deep", {
  enum: [{ a: 1 }, { b: [1, 2] }]
}, [{ a: 1 }, { b: [1, 2] }], [{ a: 2 }, { b: [2, 1] }, { c: 3 }])

// const deep equality (bonus)
check("const deep", {
  const: { a: [1, 2] }
}, [{ a: [1, 2] }], [{ a: [2, 1] }])

// if/then/else
check("if then", {
  type: "number",
  if: { minimum: 0 },
  then: { maximum: 10 },
  else: { minimum: -10 }
}, [0, 10, -5], [11, -11])

// if alone no-op
check("if alone", { if: { type: "string" } }, [1, "a", {}], [])

// then without if no-op
check("then without if", { then: { type: "string" } }, [1, "a"], [])

// boolean schemas
check("if true", { if: true, then: { type: "string" } }, ["a"], [1])
check("if false", { if: false, else: { type: "number" } }, [1], ["a"])

// implicit object type
check("implicit object", { properties: { foo: { type: "string" } }, required: ["foo"] }, [{ foo: "a" }], [{}, { foo: 1 }])

// recursive ref anyOf
check("recursive anyOf", {
  $defs: {
    Node: {
      anyOf: [
        { type: "null" },
        { type: "object", properties: { value: { type: "string" }, next: { $ref: "#/$defs/Node" } } }
      ]
    }
  },
  $ref: "#/$defs/Node"
}, [null, { value: "a", next: null }, { value: "a", next: { value: "b", next: null } }], [{ value: 1 }, { value: "a", next: 1 }])

// recursive ref in dependentSchemas
check("ref in dependentSchemas", {
  type: "object",
  $defs: {
    Node: { type: "object", properties: { v: { type: "string" } } }
  },
  dependentSchemas: { node: { $ref: "#/$defs/Node" } }
}, [{ node: { v: "x" } }], [{ node: { v: 1 } }, {}])

// nested if/then/else
check("nested if", {
  type: "number",
  if: { minimum: 0 },
  then: {
    if: { maximum: 10 },
    then: { maximum: 5 }
  },
  else: { maximum: -1 }
}, [3, -5], [7, 0])

// $ref used in allOf
check("ref in allOf", {
  $defs: { Positive: { type: "number", minimum: 0 } },
  allOf: [{ $ref: "#/$defs/Positive" }, { type: "number", maximum: 10 }]
}, [0, 5, 10], [-1, 11])

console.log("done")

