import { type } from "arktype"

interface Ctx { defs: any; cache: Map<string, any>; inProgress: Set<string>; wrappers: Map<string, any> }
function makeCtx(defs: any): Ctx { return { defs, cache: new Map(), inProgress: new Set(), wrappers: new Map() } }
function resolveDef(name: string, ctx: Ctx): any {
  const cached = ctx.cache.get(name); if (cached) return cached
  ctx.inProgress.add(name)
  const t = parseJsonSchema(ctx.defs[name], ctx); ctx.cache.set(name, t); ctx.inProgress.delete(name); console.log("cached", name); return t
}
function parseRef(name: string, ctx: Ctx): any {
  if (ctx.cache.has(name)) return ctx.cache.get(name)
  if (!ctx.inProgress.has(name)) return resolveDef(name, ctx)
  let w = ctx.wrappers.get(name)
  if (!w) {
    w = type.unknown.narrow((data, tctx: any) => {
      console.log("wrapper", name, JSON.stringify(data), "seen", tctx.seen)
      const key = `def.${name}`
      const seen = tctx.seen[key]
      if (seen?.includes(data)) { console.log("cycle hit", name); return true }
      tctx.seen[key] = seen === undefined ? [data] : [...seen, data]
      const resolved = resolveDef(name, ctx)
      const r = resolved.traverseAllows(data, tctx)
      console.log("wrapper result", name, r)
      return r as boolean
    })
    ctx.wrappers.set(name, w)
  }
  return w
}
function parseJsonSchema(schema: any, ctx: Ctx): any {
  if (schema.$ref) return parseRef(schema.$ref.replace("#/$defs/", ""), ctx)
  if (schema.anyOf) return schema.anyOf.map((s: any) => parseJsonSchema(s, ctx)).reduce((a: any, b: any) => a.or(b))
  if (schema.type === "object") { const p: any = {}; for (const [k,v] of Object.entries(schema.properties ?? {})) p[k] = parseJsonSchema(v, ctx); return type({...p}) }
  if (schema.type === "null") return type("null")
  return type("unknown")
}
const defs = { N: { anyOf: [ { $ref: "#/$defs/N" }, { type: "null" } ] } }
const ctx = makeCtx(defs)
const T = parseRef("N", ctx)
console.log("T expr:", (T as any).expression)
try { console.log("null:", T.allows(null)) } catch (e) { console.log("null ERROR", (e as Error).message) }

